mutation InvoiceEmailSend($id: ID!) {
  invoiceSendNotification(id: $id) {
    errors {
      ...InvoiceError
    }
    invoice {
      ...Invoice
    }
  }
}

fragment InvoiceError on InvoiceError {
  code
  field
  message
}

fragment Invoice on Invoice {
  id
  number
  createdAt
  url
  status
}
